"""Extraction logic. All page text here is fake, and the PDFs are generated by the tests."""

from pathlib import Path

import numpy as np
import pymupdf
import pytest

from questioniq.config import load_config
from questioniq.extract import (
    PageText,
    character_error_rate,
    clean_page,
    extract_cached,
    extract_text,
    is_table_page,
    load_cache,
    load_pages,
    mean_confidence,
    normalize_for_cer,
    render_page,
    save_cache,
    words_to_text,
)

CONFIG_PATH = Path(__file__).resolve().parent.parent / "config.yaml"
TEXT = "\n".join(["Toy line of text used only by this test."] * 4)


def word(text: str, left: int, line: str = "1.1.1", conf: int = 90) -> dict:
    return {"text": text, "left": left, "top": 0, "width": 10, "height": 10, "conf": conf, "line": line}


def text_pdf(path: Path) -> Path:
    """Write a PDF with a real text layer."""
    document = pymupdf.open()
    document.new_page().insert_text((72, 72), TEXT, fontsize=14)
    document.save(path)
    return path


def scanned_pdf(path: Path) -> Path:
    """Write a PDF whose only content is a picture of text, like a scan."""
    source = pymupdf.open()
    source.new_page().insert_text((72, 72), TEXT, fontsize=14)
    picture = source[0].get_pixmap(dpi=200).tobytes("png")
    document = pymupdf.open()
    page = document.new_page()
    page.insert_image(page.rect, stream=picture)
    document.save(path)
    return path


def synthetic_page() -> np.ndarray:
    """A white page with a light gray band (like a watermark) and a dark block (like text)."""
    gray = np.full((100, 100), 250, np.uint8)
    gray[10:30, 10:90] = 215
    gray[60:80, 10:90] = 20
    return gray


def test_otsu_keeps_dark_text_and_removes_light_watermark() -> None:
    cleaned = clean_page(synthetic_page(), "otsu")
    assert cleaned[70, 50] == 0
    assert cleaned[20, 50] == 255
    assert cleaned[50, 50] == 255


def test_adaptive_returns_a_black_and_white_page() -> None:
    cleaned = clean_page(synthetic_page(), "adaptive")
    assert cleaned.shape == (100, 100)
    assert set(np.unique(cleaned)) <= {0, 255}


def test_clean_page_rejects_an_unknown_method() -> None:
    with pytest.raises(ValueError):
        clean_page(synthetic_page(), "magic")


def test_words_to_text_moves_marks_and_co_after_a_tab() -> None:
    words = [word("Define", 100), word("entropy", 200), word("10.0", 900), word("(LO3)", 960)]
    assert words_to_text(words, 1000, 0.8) == "Define entropy\t10.0 (LO3)"


def test_words_to_text_keeps_ordinary_words_in_the_right_zone_in_the_body() -> None:
    words = [word("Define", 100), word("entropy", 850)]
    assert words_to_text(words, 1000, 0.8) == "Define entropy"


def test_words_to_text_leaves_numbers_outside_the_right_zone_in_the_body() -> None:
    assert words_to_text([word("Find", 100), word("5", 300)], 1000, 0.8) == "Find 5"


def test_words_to_text_recognises_misread_co_labels() -> None:
    assert words_to_text([word("Text", 100), word("COl", 900)], 1000, 0.8) == "Text\tCOl"


def test_words_to_text_keeps_reading_order_of_lines_and_sorts_words_within_each() -> None:
    words = [word("one", 100, "1.1.1"), word("two", 200, "1.1.2"), word("line", 100, "1.1.2")]
    assert words_to_text(words, 1000, 0.8) == "one\nline two"


def test_mean_confidence() -> None:
    assert mean_confidence([word("a", 0, conf=80), word("b", 0, conf=91)]) == 85.5
    assert mean_confidence([]) is None


def test_is_table_page_spots_grids_of_digits() -> None:
    assert is_table_page(" ".join(["0.5000", "0.5040", "1.96"] * 20))


def test_is_table_page_ignores_questions_with_some_numbers() -> None:
    assert not is_table_page(" ".join(["Find", "the", "mean", "of", "5", "and", "7"] * 10))


def test_is_table_page_ignores_short_pages() -> None:
    assert not is_table_page("1 2 3 4 5")


def test_cer_of_identical_text_is_zero() -> None:
    assert character_error_rate("abcd", "abcd") == 0


def test_cer_counts_edits_over_reference_length() -> None:
    assert character_error_rate("abcd", "abxd") == 0.25
    assert character_error_rate("abcd", "abd") == 0.25
    assert character_error_rate("abcd", "abcde") == 0.25


def test_cer_rejects_an_empty_reference() -> None:
    with pytest.raises(ValueError):
        character_error_rate("", "abc")


def test_normalize_for_cer_drops_table_rules_and_extra_space_but_keeps_case() -> None:
    assert normalize_for_cer("| Q1. |  Find\tX _\n") == "Q1. Find X"


def test_text_layer_pages_skip_ocr(tmp_path: Path) -> None:
    pages = extract_text(text_pdf(tmp_path / "t.pdf"), load_config(CONFIG_PATH))
    assert pages[0].has_text_layer and not pages[0].ocr_used
    assert "Toy line of text" in pages[0].text


def test_scanned_pages_use_ocr_and_keep_word_positions(tmp_path: Path) -> None:
    pages = extract_text(scanned_pdf(tmp_path / "s.pdf"), load_config(CONFIG_PATH))
    assert pages[0].ocr_used and not pages[0].has_text_layer
    assert "Toy line of text" in pages[0].text
    assert pages[0].words and "left" in pages[0].words[0]
    assert pages[0].mean_conf > 50


@pytest.mark.parametrize("method", ["otsu", "adaptive", "layers"])
def test_render_page_returns_an_image_for_every_method(method: str, tmp_path: Path) -> None:
    with pymupdf.open(scanned_pdf(tmp_path / "s.pdf")) as document:
        image = render_page(document, 0, method, 100)
    assert image.ndim == 2 and image.size > 0


def test_cache_round_trip(tmp_path: Path) -> None:
    pages = [PageText(1, "fake", False, True, False, 80.0, [word("fake", 1)])]
    save_cache("7", "otsu", pages, tmp_path)
    assert load_cache("7", tmp_path, "otsu") == pages


def test_cache_from_another_method_is_not_used(tmp_path: Path) -> None:
    save_cache("7", "otsu", [PageText(1, "fake", False, True)], tmp_path)
    assert load_cache("7", tmp_path, "adaptive") is None
    assert load_cache("8", tmp_path, "otsu") is None


def test_load_pages_rechecks_table_pages_with_the_current_settings(tmp_path: Path) -> None:
    cfg = load_config(CONFIG_PATH)
    cfg["paths"]["ocr"] = str(tmp_path)
    grid = " ".join(["0.5", "1.96", "fake"] * 15)
    save_cache("7", cfg["extraction"]["method"], [PageText(1, grid, False, True, False)], tmp_path)
    assert load_pages("7", cfg)[0].is_table
    assert load_pages("8", cfg) is None


def test_extract_cached_runs_ocr_only_once(tmp_path: Path) -> None:
    cfg = load_config(CONFIG_PATH)
    cfg["paths"]["ocr"] = str(tmp_path / "ocr")
    pdf = text_pdf(tmp_path / "t.pdf")
    first = extract_cached(pdf, "7", cfg)
    pdf.unlink()
    assert extract_cached(pdf, "7", cfg) == first
